public class LruCache<TKey, TValue> where TKey : notnull
{
    private readonly int _capacity;
    private readonly Dictionary<TKey, LinkedListNode<(TKey Key, TValue Value)>> _nodes = new();
    private readonly LinkedList<(TKey Key, TValue Value)> _order = new();

    public LruCache(int capacity)
    {
        if (capacity < 1) throw new ArgumentOutOfRangeException(nameof(capacity));
        _capacity = capacity;
    }

    public int Count => _nodes.Count;
    public IEnumerable<TKey> KeysByRecency => _order.Select(entry => entry.Key);

    public bool TryGet(TKey key, out TValue value)
    {
        if (_nodes.TryGetValue(key, out var node))
        {
            _order.Remove(node);
            _order.AddFirst(node);
            value = node.Value.Value;
            return true;
        }
        value = default!;
        return false;
    }

    public void Set(TKey key, TValue value)
    {
        if (_nodes.TryGetValue(key, out var existing))
        {
            _order.Remove(existing);
            _nodes.Remove(key);
        }
        else if (_nodes.Count == _capacity)
        {
            var oldest = _order.Last!;
            _order.RemoveLast();
            _nodes.Remove(oldest.Value.Key);
        }
        _nodes[key] = _order.AddFirst((key, value));
    }
}

unitTests:
Test("drops the least recently used", () =>
{
    var cache = new LruCache<string, int>(2);
    cache.Set("a", 1);
    cache.Set("b", 2);
    Check(cache.TryGet("a", out int a) && a == 1, "a should be there");
    cache.Set("c", 3);
    Check(!cache.TryGet("b", out _), "b was the least recently used and should be gone");
    CheckEq(cache.KeysByRecency, new[] { "c", "a" });
    CheckEq(cache.Count, 2);
});

Test("replacing a value refreshes it", () =>
{
    var cache = new LruCache<int, string>(2);
    cache.Set(1, "one");
    cache.Set(2, "two");
    cache.Set(1, "uno");
    cache.Set(3, "three");
    CheckEq(cache.KeysByRecency, new[] { 3, 1 });
    Check(cache.TryGet(1, out var v) && v == "uno", "1 should hold its new value");
});

Test("capacity", () =>
{
    CheckThrows<ArgumentOutOfRangeException>(() => new LruCache<int, int>(0));
    var one = new LruCache<int, int>(1);
    one.Set(1, 1);
    one.Set(2, 2);
    CheckEq(one.KeysByRecency, new[] { 2 });
});

